-- Restore only as part of a reviewed full rollback transaction.
create or replace function public.ca_v2_public_weekend(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$declare hashed text;bucket timestamptz=date_trunc('minute',now());hits integer;begin if length(p_token)<>64 or p_token !~ '^[a-f0-9]+$' then raise exception 'Link unavailable';end if;hashed=encode(extensions.digest(p_token,'sha256'),'hex');insert into ca_private.v2_public_limits(token_hash,bucket,hits) values(hashed,bucket,1) on conflict(token_hash,bucket) do update set hits=v2_public_limits.hits+1 returning v2_public_limits.hits into hits;if hits>60 then raise exception 'Too many requests. Try again shortly.';end if;return(select snapshot from ca_private.weekend_publications where token_hash=hashed);end $$;
